LOCK TABLES `comments_七武士` WRITE;
/*!40000 ALTER TABLE `comments_七武士` DISABLE KEYS */;
INSERT INTO `comments_七武士` VALUES (1,1,'托尼·王大拿','力荐','我只能用”高山仰止”四字来形容我对黑泽天皇这部旷世杰作的仰慕之情；纷繁庞杂却又条理清晰的史诗，严苛而精准的镜头和构图，七个武士和若干农民的性格都被描绘得入木三分， “休憩”后的大决战无比恢弘，叹为观止。','2011-03-08 08:07:27'),(2,2,'[己注销]','力荐','原以为我会觉得“那时候能够拍成这样已经很了不起了”，看完后才知道“这种拍摄效果今天很多导演尤其中国导演都拍不出来”……\n2019年重看了本片，发现了不少细节。故事开头找武士同伴，师父让徒弟用木棒袭击武士时，几个农民赶紧往后退，由于后退得太自然，以往这个细节被我忽略了，但这个后退的动作，却说明了农民把责任推给了武士（师父），不想承担被袭击武士的怒意，尽管他们才应该是主要责任人、而不是被他们雇佣的师父。还有徒弟暗中出钱让农民买米，这是一份恩情，但之后师父考虑徒弟年轻不让他参加打斗时，农民却巴不得徒弟凑个人数。当然黑泽明没有无脑黑农民，正如菊千代所说，农民虽然狡猾和自私，但这是武士阶级的战争造成农民这样的性格。武士很傲慢，农民也很自私，而双方都有各自的痛苦，见证这一切的，则是想当武士的农民菊千代。','2010-06-05 22:16:29'),(3,3,'deepwhite2333','力荐','看完把我累死了。。。','2008-12-26 13:08:08'),(4,4,'沉歌','力荐','完成度之高啊！三个半小时下来连个低潮都没有，后来的《影武者》、《乱》都比不过这部。每个人物性格都非常鲜明，志村乔仿佛一灯大师，三船敏郎似韦小宝，久葬是独孤求败，胜四郎像段誉……唯一的问题是志村乔剃完头怎么这么像张丰毅呀？！','2013-04-14 23:24:33'),(5,5,'seeme | 北北','力荐','我什么话都么的说。什么叫NB，这就叫NB。','2008-11-17 20:02:36'),(6,6,'暖鱼','力荐','和教父是一种类型的电影，突出人物性格，故事情节也曲折。最后真的是人民战争海洋。很有几次，都觉得这也可以算一部写中国人的电影，比如农民的狡猾与认命等，到最后的我能！','2009-03-22 00:04:35'),(7,7,'鸳鸯','推荐','赢的是那些农民，不是我们。','2009-06-01 13:02:49'),(8,8,'阿树','推荐','劇本的言外之意在結尾已經很明顯。農民獲勝就無視武士的付出。他們既可以殺害落魄武士搶奪他們的物品，也可以把弱小當作自己的武器吸引落魄武士的同情，利用他們保護自己，所以菊千代說農民是自私醜陋的。但武士終究貫徹自己的道義為民守城，這是寫給武士的讚歌，但也是武士的悲歌。結尾的對白太心酸','2017-01-11 21:09:37'),(9,9,'艾小柯','力荐','经典杰作，宏大与细腻并重，形式与主题俱佳，堪称模本。','2011-07-13 11:32:51'),(10,10,'影志','力荐','怎么说服人，怎样坚持，怎样欲擒故纵、运筹帷幄…无以复加的经典！原来经典并不是多复杂，反而更简单。故事线索逻辑清晰，战斗开始后的每死一个人，观众都能跟导演一样明白清楚。','2017-06-28 11:06:32'),(11,11,'玉麒麟宋哪吒','力荐','志乃的发型很时尚嘛','2008-11-15 01:17:42'),(12,12,'cruyff','力荐','五十多年前的动作片，久看不厌，历久常新，大师的功力不同凡响','2007-08-18 14:55:37'),(13,13,'冉笛','力荐','我们又失败了，那些农民才是胜利者。武士就像风，从大地上漫卷而过，那些农民始终和大地在一起，永远地活下去。——武士拼死相搏，故事的终局却连他们安身立命的信条都给颠覆了，黑泽明这一刀实在是够狠，就是这种狠劲，给我们看见人性的真实和历史的严酷','2010-08-17 23:12:21'),(14,14,'深山夜读','力荐','保卫家园的片子，也能拍出如此深刻的人性。','2007-07-27 01:05:10'),(15,15,'朔風','力荐','舍生取义，虽千万人吾往矣，所以士死得最快。随着他们的逐渐消亡，气节、德行和高贵的理想也一去不复返。庶民日复一日的耕种自己那块小田地，他们不懂什么礼义廉耻，也不愿意负责，只想混日子，这种认命和麻木却赋予他们顽强的生命力。而笑到最后的，永远是那些唯利是图且不择手段的人。','2013-04-29 08:22:43');
/*!40000 ALTER TABLE `comments_七武士` ENABLE KEYS */;
UNLOCK TABLES;

