LOCK TABLES `comments_三块广告牌` WRITE;
/*!40000 ALTER TABLE `comments_三块广告牌` DISABLE KEYS */;
INSERT INTO `comments_三块广告牌` VALUES (1,1,'哪吒男','推荐','本届奥斯卡主题——美国妈妈牛逼死了。《伯德小姐》《我花样女王》《大病》《三块广告牌》拜托把这几个妈妈凑在一起吧，光聊天吵架就行，比超级英雄联盟好看一万倍。','2018-01-03 12:30:50'),(2,2,'桃桃林林','力荐','这部竟然拍得非常温柔，有点落寞和伤感，看完会被人的善良所打动。虽然确实有些天真，但还是好爱这样的电影，会让你很享受这个故事。当然，导演之前擅长的喜剧部分仍然很到位。几个演员都非常出色，女主和两个男配，写得好，演得更好。挺奥斯卡的片，应该能有斩获吧。','2017-11-14 21:16:46'),(3,3,'豆瓣浅度用户','推荐','胖牙医十分可疑','2017-09-04 19:26:55'),(4,4,'烤芬','未评分','麦克唐纳真的太会写对白了，女主每次怼人都怼得很精彩（怼完神父全场掌声雷动hhh），而她怼得越畅快，就越有“一人对抗全世界“的孤胆气概；越坚强就越寂寞、越寻找就越绝望，这是属于小人物的日常英雄/反英雄瞬间，是麦又一次用十分擅长的荒谬口吻讲述了一个沉重的、很人性的故事。','2017-09-07 04:57:54'),(5,5,'大島','力荐','我的情绪和观点在这100分钟里面不停地翻转和颠覆','2018-01-21 11:19:35'),(6,6,'张天翼','力荐','三块火一样烧红的广告牌，三个人，三封信。角色的面目都是逐渐清晰起来的，就像警局里前一秒两人还针锋相对，局长意外吐血，米尔德脱口而出一句“baby”。全片就是充满那样意外又令人心软的转折。','2018-01-09 15:40:39'),(7,7,'亵渎电影','推荐','一直觉得马丁·麦克唐纳是继昆汀·塔伦蒂诺之后最有才华的编剧，他的剧本每次都是超高的难度，既有一流的编剧技巧又有严肃的文学性。他总是以黑色和荒诞的东西先爽到你，最后再慢慢的用正能量感动你，让你在残酷的生活里看到一丝人性的暖色。这次的人物塑造很厉害，最佳群像表演也是这个剧本的功劳。','2018-01-03 13:00:44'),(8,8,'同志亦凡人中文站','推荐','今年两大最政治不正确电影之一（另一部是《凭空而来》）。愤怒是活下去的动力，怼天怼地才能内心平静，麦克唐纳用冲天戾气和负能量熬出一碗悲喜交加的心灵鸡汤。科恩嫂的表演太炸裂了，枯瘦的身躯下隐藏着滚烫的力量，全片仅有的一次笑容锁定奥提...','2017-11-30 15:58:02'),(9,9,'谢飞导演','力荐','老套的寻凶复仇故事讲述得如此生动，编剧值一颗星；情节似层层剥笋，露出的是七八个清晰、独特、复杂的人物，两个星给予出色的女主演及男配角；将视觉场面、音乐服化等手段与叙事有节奏的、完整地掌控融合起来，应是导演获得的一颗星；结尾高明的情节逆转和开放式，为这部电影赢得了最后一颗星。满分！','2018-01-09 17:22:59'),(10,10,'西楼尘','推荐','我对生活从无迷信，为何对女儿的诅咒却一语成谶？我以为世间应有上帝，奈何却被邪佞玩弄股掌。没人告诉女人在丈夫自尽后的一天该做什么，也没人知道母亲在女儿奸杀后的半生能做什么。在血色晚霞里涂上殷红的广告牌，它早晚会在烈火里被遗弃。幸好在斑驳之前，每个经过它的人都看过上面狰狞的字，正义。','2018-02-25 10:38:35'),(11,11,'影志','力荐','一晚上居然写了三封信！厉害了Woody叔。环环相扣，宿命轮回，错与对的双刃剑，比《杀手没有假期》更以小见大，提前预定今年奥斯卡最佳影片。女主、双男配演技巅峰，群戏也个个出色，剧本无可挑剔，开放式结局令人唏嘘…“-你确定我们还要这么做吗？-我不确定。-我们可以路上慢慢决定”','2018-01-03 22:41:28'),(12,12,'Sgt.Donuts','推荐','蹦出一条小鹿这个必须减分了…而且还那么像CG做的…','2017-12-08 11:29:37'),(13,13,'焚紙樓','很差','一個只因木牌爛掉就怒拿油彈炸警局（還是間敢動私刑的黑局）的母親，何以在女兒被姦殺後整整七個月毫無動靜？如此關鍵而撕裂的人物動機的空白，不可能也不該靠一句「憤怒只會招致更大的憤怒」就打發，復頌幾次都一樣；何況我根本想不出，有哪一種憤怒能比人母得知女兒慘死當下的那一種更巨大、更極限。','2018-02-15 00:09:07'),(14,14,'陀螺凡达可','还行','这题材太适合奥斯卡最佳影片了，完全贴合美国社会热点。人物和结尾写得不错，洛克威尔是目前为止我心目中的年度最佳男配。Burwell的配乐动人。但是麦克唐纳再次证明他是一个精于算计的戏剧编剧而不是一个优秀的电影导演。以及大家称赞群像表演时请把艾比·考尼什排除在外谢谢。','2017-10-22 06:07:42'),(15,15,'胤祥','力荐','#Venice2017# 影后已出。真是教科书一般的好剧本，破了不少套路，人物塑造十分生动。再加上导演控制力很强，不乏幽默感，也有不错的社会观察。对仇恨与愤怒的探讨颇有与当下社会状况的契合点。','2017-09-04 19:48:11');
/*!40000 ALTER TABLE `comments_三块广告牌` ENABLE KEYS */;
UNLOCK TABLES;

