/*!40000 ALTER TABLE `comments_寄生虫` DISABLE KEYS */;
INSERT INTO `comments_寄生虫` VALUES (1,1,'蚂蚁没问题','力荐','这部电影最伟大的地方就是，有钱人实际上是什么都没做错的，夫妻恩爱，儿女喜人，没有出轨，没有冷暴力，没有虐待儿童，对司机、佣人也大方不抠门，他们真的真的善良单纯，但是你就是忍不住恨他们，恨他们，恨他们。','2019-08-08 00:04:31'),(2,2,'西楼尘','推荐','沐浴庭院里的阳光就能进化成人，呼吸暗室里的空气只会走肉如鬼。抱上贫穷的石头终生无法脱手，染上廉价的气味永世不能消除。蜷缩地下的臭虫，用药剂开窗替自己杀菌；位居高处的宿主，用金钱雇人给自己消毒。富人吸着穷人的血高升，穷人寄在富人的屋苟活，人鬼同处一室分享食物，虫兽寄生一体发育恩仇。','2019-07-07 15:19:04'),(3,3,'大旗虎皮','推荐','我先来第一瓢凉水吧，富人的形象太简单了，富人很傻吗？?','2019-06-22 14:38:18'),(4,4,'舒农','推荐','这片子口碑爆炸，只能说明，平时看了100部文艺片，人类的本质还是喜欢商业类型电影。','2019-05-22 17:12:49'),(5,5,'Peter Cat','推荐','奉俊昊才是我们时代（各种）类型大师。','2019-05-22 07:12:56'),(6,6,'南悠一','推荐','像是被朴赞郁和李沧东都附了体，奉俊昊显然受Netflix创作理念影响了，他用商业套路向我们证明，情节剧在表达社会苦难上的伟大，且他是以戏谑的形式讲述。电影将韩国社会阶层（与《燃烧》同一主题，可见韩国社会阶层问题的严重）问题，设计为一个戏剧张力很强、悬疑感十足的巧妙的小人物故事。片名寄生虫是个隐喻，而石头也是个隐喻，大量涉及政治背景的边角作为点缀，大量台词都可以高亮划出来当金句。然而，这部电影虽然非常非常非常好看，它无论如何都讲得太明白了，我绝对不会再看第二遍，没意思。','2019-05-22 07:20:09'),(7,7,'朝暮雪','力荐','一边是水淹陋室，一边是生日聚会。\n一边是冰冷坚硬的体育馆，一边是豪华柔软的后花园。\n钱就是熨斗，把一切都烫平了。\n他们蹭网、住地下室、为了一份工作不择手段。\n当你觉得他们已经够惨的时候，电影突然反转：他们还不是最惨的，还有更惨的。\n你富，就一定有比你更富的；你穷，也一定有比你更穷的。\n贫富差距就像无数面墙，将人分为了三六九等。\n这面墙，任凭风吹日晒雨淋也岿然屹立，纹丝不动。\n朴夫妇看起来傻乎乎的，可他们还是越来越有钱；\n金基泽一家聪明过人，可还是翻不了身。\n你以为找个好工作，有份好薪水，就摆脱了贫穷的身份，其实还差了十万八千里。\n你能洗掉衣服的汗味，却洗不掉已经融入血液的地下室的气味。\n你爬了十层楼、二十层楼，可能才刚刚到达别人的地下室。\n他们是虫子，所以他们生活艰难；\n他们是虫子，所以什么都杀不死他们。','2019-08-07 09:41:47'),(8,8,'违规昵称6789','力荐','不得奥斯卡最佳外语片我吃键盘','2019-05-26 10:55:03'),(9,9,'frozenmoon','推荐','《燃烧》根本不是现实批判的框架，和阶层阶级什么的毫无关系，那个电影探讨的是“存在是否有意义”，完全哲学化的，但这个才是阶级和阶层的故事。好看是没得可挑剔的，但就是都过于直白了，气味、石头、蟑螂，隐喻变成明喻，象征近乎叫嚷。《燃烧》可以看很多遍，这个可以好好看一遍。技术层面的公正和纯熟大于内容和所谓的意义。','2019-08-08 12:51:02'),(10,10,'豆瓣浅度用户','推荐','时间和空间的掌控力都很巧妙，奉俊昊是不是窥破宇宙的真谛了？','2019-05-22 06:45:40'),(11,11,'千舟','力荐','那些只会镜头往那一杵，不把人拍睡着不罢休的国内艺术片导演可以学学，电影到底是啥，啥叫剧作节奏，镜头语言，剧本钩子，一天天竟沉浸在自己的艺术国度里意淫，中国电影就是被那些新浪潮的忠实信徒带跑偏了，因为不会技术，美名冠曰搞艺术，看十分钟就关了，抓不住观众你在那拍你?艺术呢？用吸引人的视听前提去解构故事的隐喻和主题，这才是懂电影，才是拍电影，同样是长镜头，人家拿来做剧情反转，这明显在怼只会用长镜头做自己技术遮羞布的艺术片导演，从电影市场看充满讽刺。你可以说韩国电影翻来覆去总是那些很黑暗的题材，但他们现在至少在电影的视听技法上（摄影，灯光，剪辑）是亚洲的扛把子。商业节奏≠商业片，用商业节奏去讲艺术才是电影该做的事啊！','2019-05-26 08:22:06'),(12,12,'Lies of Lies','推荐','一个无尽的玩笑，直到最后一个镜头前都保持了刀尖上的平衡。地下室气味催发了社长夫妇的情欲，生日宴会的楼上是亲吻的年轻人，不是很有福楼拜农展会的趣味么？影片不仅仅书写了一段封闭叙事，也构筑了一种永恒的共生关系，躲在地下的诺斯费拉图随时可能回来夺取政权。','2019-08-08 02:58:09'),(13,13,'孔鲤','力荐','看完《寄生虫》，一直和大家一个想法，隐喻太明显，结果对了一下，发现大家的隐喻体系都不一样。这电影在我看来讲的就不是阶级的事。讲的是韩国自己。朴社长那家人，从头到尾都流露出两个字：美国。儿子的印第安控，女儿的外语老师，夫人时不时蹦出的英语和社长公司里的美国奖状。这一家象征着什么？别忘了，这一家是搬过来的，在搬过来之前有一户人家为了防止北边而修了地下室，那这个年代就能基本确定了。这和韩国史是对应的。我们还可以再来看一个细节，假装自己是美国留学回来的妹妹去应聘时，哼的歌是《独岛是我们的领土》。寄生虫，寄生的可不只是阶级，更多说的是韩国自己。','2019-08-11 20:22:24'),(14,14,'暖小喵','推荐','说实话，我有一点失望。确实是构思的很巧妙，非常好的故事，环环相扣，各种反转，演员的表演也非常出色。但最后还是有点落入韩影的惯常套路。现在能理解导演为什么说不能剧透了，因为如果剧透的话此片的可看性会大大降低。讽刺，冷幽默，对社会问题的反思，这些都感受到了。但对不起，这真的不是我所期待的金棕榈。','2019-05-29 04:12:36'),(15,15,'胤祥','推荐','#72nd Cannes# 金棕榈。奥斯卡BP/BD/国际影片/原创剧本+美指、剪辑提名。把一个怎么看都该是惊悚片的故事拍成High翻全场的爆笑喜剧，还不忘对社会问题的犀利揭示，奉俊昊的无比精彩的最新作品《寄生虫》的确配得上一个编剧奖或者导演奖。影片是一个精心构思，多重反转的社会寓言，深挖“阶级鸿沟”的议题，与《燃烧》确乎能形成某种意义上的对照关系，但同样与《小偷家族》有着某种意义上的呼应关系。不能剧透的前提下分析导演技巧，大概最值得赞美的是其中结构性的大量匹配剪辑手法，在形成强烈对比之余，又通过这一手法来铺排线索，形成剧作悬念。影片最痛楚的一个情节点莫过于对气味的强调，低阶级的人们身上的气味相似，而且无法掩藏，而且成为了无法跨越的鸿沟。当然剧作精彩之余又不免过于依赖巧合和意外事件，稍稍有些遗憾。','2019-05-22 17:57:18');
/*!40000 ALTER TABLE `comments_寄生虫` ENABLE KEYS */;
UNLOCK TABLES;

