LOCK TABLES `comments_布达佩斯大饭店` WRITE;
/*!40000 ALTER TABLE `comments_布达佩斯大饭店` DISABLE KEYS */;
INSERT INTO `comments_布达佩斯大饭店` VALUES (1,1,'Dude','力荐','《布达佩斯大饭店》，配得上太多赞美的词汇，但是电影最后的十几分钟，我内心感到了一股深刻却难以名状的悲伤，想了好久，也想不明白是为什么。走出电影院，感觉就像做了一场梦一样，似乎历历在目，却又难以言说。','2014-03-17 15:11:41'),(2,2,'毛','还行','原谅我从头到尾都没入戏........好吧我对Wes Anderson的确审美疲劳了........','2014-04-04 00:57:32'),(3,3,'亵渎电影','力荐','这不仅仅是一部电影，它是游戏，是童话，还是一件艺术品，将作者化的美学风格、形式感和怀旧的主题完美融合！无论从故事、剧作、主题和美学，它的辨识度都只属于自己，对于韦斯·安德森的粉丝，这是杰作！','2014-06-05 23:20:24'),(4,4,'江声走','推荐','打动我的是那位面对蛋糕切不下手的士兵。也许这是整部电影想要讲述的核心。','2021-01-07 23:16:28'),(5,5,'玑衡','力荐','非常好。像一杯温暖的热可可，做得如此甜蜜却又不轻佻，好多台词和段子都有所指涉，却又浑然天成，不像在掉书袋。片尾看到对茨威格的致敬，眼泪都掉下来了。自从好多年前看了Visconti的《豹》之后，这是第二部让我对“昨日的世界”充满向往的电影。','2014-03-22 12:05:29'),(6,6,'鸟仔','力荐','四重讲述空间，层层递进，宛如俄罗斯套娃。依次揭开，掏出一个如万花筒斑斓的昨日世界: 单线故事情节串起性格迥异的众多出场人物。场景切换如同梦境接力。现实与虚幻交织，严肃与荒诞同存，甜美和苦涩共生。整体观感相当有趣又十分充实。最后必须咆哮一句，满屏的演技帝甜得简直人神共愤！','2014-03-17 09:36:44'),(7,7,'木卫二','力荐','他，还有她，就那样离开了，昨日的世界也不复存在。','2014-03-31 22:13:31'),(8,8,'牛腩羊耳朵','力荐','四重时空与讲述方式以及画幅的迷人结构【越靠近现在越狭窄间接】，主体故事全景描绘了欧洲战前文化褪色的最后辉煌【礼数，名画，家族】，作为见证者的Zero【移民】对依然消失的“精神家园欧洲”的怀旧感，以及对老电影的表演方式和镜头运用的模仿致敬，加上费因斯的精妙表演与卡司，安德森迈入大师门槛','2014-02-28 07:50:40'),(9,9,'柏林苍穹下','力荐','“微弱的文明之光，仍存留在这野蛮的屠场里，这就是人性。”——维斯·安德森致敬斯蒂芬·茨威格，小清新的故事里注入了大历史的情怀。','2014-06-05 21:24:41'),(10,10,'唐小万','推荐','依然还是韦斯-安德森标志性的复古色调、悦耳配乐，神经兮兮的冷幽默。不像前作那么随意松散，《大饭店》故事紧凑、层层剥茧，而且居然有点“重口味”。也许只有韦斯-安德森才能把一个混合谋杀、越狱、械斗的故事拍得那么喜感。','2014-02-06 23:07:09'),(11,11,'Iberian','未评分','“His world had vanished long before he ever entered it, but he certainly sustained the illusion with a remarkable grace.”这句话说出来的时候我就想拜倒在WA的剧本下了，这句话无比精准的概括了整个故事和男主的一生，写的太美了。画面也美，就像给眼睛吃Mendl\'s的点心','2014-03-24 10:11:19'),(12,12,'大奇特(Grinch)','力荐','韦斯最高度风格化的电影，充分体现了他对镜头调度、色彩照明的掌控和微缩模型的精妙，并依然热衷于演员如何出现在镜头前及走位；画幅比也加强了片子的古典氛围（古斯塔夫逃狱和零接头那场戏最具30年代老片风骨）。尽管依旧是形式大于内容，且比过去的作品少了深度与情感，但这就韦斯.安德森。','2014-06-06 09:01:17'),(13,13,'lee','力荐','竟然是以茨威格的昨日的世界为灵感的哦','2014-03-03 20:32:11'),(14,14,'K','力荐','未見過Wes如此有野心,將作者風與故事及內涵融合得非常出色,一層層的敘事模式,畫面1:85進2:35再進4:3,大量電影語言,有搞笑有奇情有懷舊有懸疑有驚慄有黑色幽默最重要有那份人性真情,明明是喜劇但最後結尾一段傷感的況味揮之不去,目前Wes處理得最成熟,圓渾之作!','2014-03-24 17:51:12'),(15,15,'水瓶座女孩','还行','告诉我！！！不是只有我一个人刷完全片就落得三个字：没看懂！！！','2022-08-18 22:40:22');
/*!40000 ALTER TABLE `comments_布达佩斯大饭店` ENABLE KEYS */;
UNLOCK TABLES;

