LOCK TABLES `comments_我不是药神` WRITE;
/*!40000 ALTER TABLE `comments_我不是药神` DISABLE KEYS */;
INSERT INTO `comments_我不是药神` VALUES (1,1,'沐子荒','力荐','王传君所有不被外人理解的坚持，都在这一刻得到了完美释放。他不是关谷神奇，他是王传君。\n你看，即使依旧烂片如云，只要还有哪怕极少的人坚持，中国影视也终于还是从中生出了茁壮的根。\n我不是药神，治不好这世界。但能改变一点，总归是会好的。','2018-07-03 22:37:38'),(2,2,'朝暮雪','力荐','这不是“中国版《达拉斯买家俱乐部》”，这是中国的真实事件改编的中国电影，是属于我们自己的电影，不知道就去百度一下“陆勇”。','2018-06-30 17:40:18'),(3,3,'西楼尘','还行','病是一种罪，上帝也不能赦免；穷是一种病，药神也无法医治。思慧把脱掉的衣服一件件穿上，黄毛把留长的头发一寸寸剪下，程勇把缺口补上，受益把口罩摘下。法和情谁上谁下，命和钱谁上谁下，灾厄的红药水抹到谁的头顶，侥幸的救世主降到何方人间。许多人终其一生都在寻一种药，没药的世界我们能不能活？','2018-07-04 17:09:27'),(4,4,'开开kerguelen','力荐','小时候路过一家药店，门口的对联写着“只愿世间无疾病，何愁架上药染尘”','2018-07-04 21:00:31'),(5,5,'七海','力荐','文牧野眼睛太毒了，观众的笑点、泪点、痛点被他牢牢抓住，徐峥现在不拼演技开始掏心炸肺放脱自我了，药物在中国绝对是个“不可说”，但这个电影说了它能说的，也不显山不漏水的说了它所不能说的，讲的是现实，但看过电影之后才会明白其实是超现实，2018最佳!','2018-06-30 19:28:36'),(6,6,'大島','力荐','你的一个举动可能会改变别人的一生，酒吧领班从此爱上了钢管舞。','2018-07-05 21:39:15'),(7,7,'Noodles','力荐','人生建议：别买零食，吃不下的。','2018-07-03 23:58:30'),(8,8,'喝可乐的鸟','力荐','炸裂，哭成狗，从观影体验上看，比达拉斯买家俱乐部好，之间隔了差不多五个《动物世界》，导演处女作就这完成度，只能说剧本实在太好。我爸爸也是药神的受益者之一，否则我应该房子也没了。感谢他们?。','2018-07-03 22:01:56'),(9,9,'袁牧','推荐','看了一下差评，基本是自诩为独立专业的几个影评人给的吧，果然又要说电影语言，商业媚俗之类，固然把这个题材拍成侯孝贤、蔡明亮那样，影评人会有高潮，但你们其实喜欢的是影院里就坐着你们两三个人那种感觉不是吗？没有这种电影，电影人在时代急速抛弃弱势群体的巨变中，就是完全失语的。','2018-07-06 16:58:09'),(10,10,'谢飞导演','力荐','祝贺学院硕士毕业生文牧野出手不凡，导演了这样一部扎实、感人、有见地的处女作！看片中常在想：在疾病、死亡面前，一些常规的道义、是非怎么都成了反意？先人说过“合情合理才是好法。”那么实践证明已经不合情理的法律规章就应该改掉它！直面现实，促人思索，这样的作品值得夸赞！','2018-07-10 15:44:56'),(11,11,'姨妈的鸭','力荐','特效是真实人性，特技是上映成功。','2018-06-30 16:06:18'),(12,12,'刘念拉','还行','怎么不能拿《达拉斯买家俱乐部》说事了？同样的题材，人家对人性挖掘地多好，我们只会煽情。','2018-07-04 15:53:16'),(13,13,'柯里昂','还行','“送出去挺好的，将来比咱们有出息”，结合全片看这句台词会非常有意思。前半段刻意营造的笑料过多，同时使得整部片的意旨变得暧昧不清，而原型人物的重量和意义也被那一个个太过戏剧性（和喜剧性）的情节所无形消解。以及，在这个首尾都需要字幕进行“立场矫正”的环境下，还是别类比《达拉斯》了吧。','2018-06-30 17:13:53'),(14,14,'麻辣香','力荐','为一句“谁家还没个病人”泪流满面 感叹生命在“穷病”面前无药可救 感慨中国终于有了属于我们自己的有力量的电影 所有演员都非常出色 近年最好的群像表演 请记住这些电影人 宁浩 文牧野 徐峥 周一围 王传君 谭卓 章宇 杨新铭 王砚辉 咱们电影还是有希望的 愿中国的电影越来越好 谢谢','2018-07-04 10:58:44'),(15,15,'小夕克莱尔','力荐','“他才20岁，想活命有什么罪”','2018-07-04 11:06:09');
/*!40000 ALTER TABLE `comments_我不是药神` ENABLE KEYS */;
UNLOCK TABLES;

