--
-- Dumping data for table `comments_步履不停`
--

LOCK TABLES `comments_步履不停` WRITE;
/*!40000 ALTER TABLE `comments_步履不停` DISABLE KEYS */;
INSERT INTO `comments_步履不停` VALUES (1,1,'萨嘎摩多熊猫桑','推荐','人生就这么步履不停地前行着，那些舍得的舍不得的人和事总会一一远去，以至再也无法望见。你可能偶尔怀念，也可能丢了命似的道不了别。','2010-03-23 10:10:52'),(2,2,'亵渎电影','力荐','亲人只有一次的缘分，无论这辈子我和你会相处多久，也请好好珍惜共聚的时光，下辈子，无论爱与不爱，都不会再见。★★★★★','2009-09-10 02:38:25'),(3,3,'水仙操','推荐','送走儿子后寡言的医生父亲念叨：“下次来的时候就是新年了。”与此同时儿子坐在远行的大巴上长舒一口气：“这次回家了新年之行总算可以省了。”转瞬下一个镜头就变成空的风景和儿子的画外音：三年后父亲死了。不多久母亲也走了，她最终也没坐上我买的车。这是日影特有的温情与残酷。玉米天妇罗。','2011-09-05 18:52:46'),(4,4,'达到厂','力荐','日本的家庭电影已经是世界巅峰了，步履不停是巅峰中的佳作。','2011-01-17 14:45:59'),(5,5,'Q。','推荐','\"你才25岁，你可以成为任何你想成为的人。\"剧情没有什么起伏，不温不火，朴实平淡的对话，安静的生活，温馨的生活细节，这样讲出来的故事，总是娓娓动人。生命依旧不停的在循环，平淡、责任、羁绊、也许，这也叫做人生吧。当最后那只黄粉蝶飞出来的时候，却让人眼泪止不住的在流。★★★★☆','2011-02-09 21:29:47'),(6,6,'丁一','推荐','夏至横山家，\n小津屋檐下，\n周围二三事，\n外婆炸玉米，\n攀折紫薇花，\n追逐黄蝴蝶。\n淡然疗心伤，\n四肢渐愈合。\n有了伴的路，\n步履停一停；\n牵了手的手，\n岁月不回头。','2010-02-27 11:28:48'),(7,7,'冰山李','力荐','9.5；和解总是慢死亡一步','2009-04-11 21:27:26'),(8,8,'文泽尔','推荐','试图用一个特殊的日子来讲述横山家数十年来的漫长岁月，不运用任何插叙，只是让时间一点点流过，从各人间的对话中了解这个家庭久远已逝的一切哀痛压抑温馨喜悦，然后日子还得淡淡前行。每个人物都刻划得立体有力，但是片长四分之三再往后有些情节：如蝴蝶入屋、孩子晨祈愿、多年后生孩子也开车等稍刻意','2010-08-07 05:33:06'),(9,9,'沉歌','力荐','我了解关于生命的哀伤，总是静默的，漫长的。','2009-04-27 17:52:59'),(10,10,'Doublebitch','力荐','我喜欢电影里的台词，真实不做作，却把这个家庭十几年隐藏的哀痛和矛盾表达的很清楚，最让人感动的莫过于倔老头子送走良多后那句像是自言自语般的，“下次来就是新年了吧”，父亲所特有的不动声色的爱啊～','2011-02-09 13:35:44'),(11,11,'亚比煞','推荐','听说蝴蝶如果能够熬过一个冬天，来年就会变成黄色。从此，我每次看到黄色的蝴蝶，心里就会难过。','2016-07-23 09:41:11'),(12,12,'Yome','推荐','生活尽管再平静偶尔也有波澜 不停走着有些东西还是趕不上。','2009-01-18 09:36:25'),(13,13,'57','力荐','东方人的日常生活中就是常常上演这种迟到的温情、无奈的残忍，并且自觉地不知悔改地步伐不停。秉承着同样的嘴硬和含蓄，他们塑造了家，捏造了国。','2011-04-26 22:05:06'),(14,14,'柏邦妮','力荐','是枝裕和说，《步履不停》是一个什么事都没发生的故事，除了细节别无旁物，因为，细枝末节累加起来即是生活。回想那一部看了无数遍的电影，不是什么事都没发生过。最喜欢一个细节是一只蝴蝶，宛如哥哥的亡灵飞过，平实的妈妈立刻狰狞如同疯魔，追逐亡故的长子的幻影。一个平常家庭的创口顿时撕裂。','2017-06-22 00:27:53'),(15,15,'同志亦凡人中文站','力荐','不知道什么时候起，一看到这种生活流的电影就泪如泉涌走不动路。人间烟火的气息，代代步履不停...','2013-12-27 22:54:30');
/*!40000 ALTER TABLE `comments_步履不停` ENABLE KEYS */;
UNLOCK TABLES;

