LOCK TABLES `comments_火星救援` WRITE;
/*!40000 ALTER TABLE `comments_火星救援` DISABLE KEYS */;
INSERT INTO `comments_火星救援` VALUES (1,1,'末药煎肉塔','推荐','很好看的太空荒野求生记，马特达蒙一定是找了裸替他不可棱瘦的下来。另外贵国是有多想赚中国市场的钱，看到国家航天局直接笑出声了','2015-10-03 11:57:00'),(2,2,'影志','推荐','孤独如《瓦力》，求生如《荒岛余生》，乐观如《鲁滨逊漂流记》，逃生如《地心引力》…没《星际穿越》那么浩瀚，一个小火星胜似一个宇宙，逗比程度也不及原著一半，更多的是硬科幻和科普纪实。但说实话，连续三年太空科幻题材，或多或少有些疲劳，拍的又如此工整，无惊艳之笔、也绝非神作。','2015-11-12 13:54:23'),(3,3,'伊谢尔伦的风','推荐','挺好看的，但我不能理解北京群众怎么可能在下雪的天气里放着好好的暖气不要，集体露天围观一个美国人的死活……想了想觉得唯一合理的解释是我国媒体报道他是一位伟大的植物学家，开创了火星农业的崭新领域，堪称火星袁隆平……大家围观直播时旁边肯定还有人卖同款火星烤土豆。','2015-11-28 19:51:39'),(4,4,'ANNA','推荐','作为一部靠谱的lifeline真人版，本片以喜庆、欢乐、祥和的风格展现了一位资产阶级话痨斗士扎根火星种植土豆开荒的故事，最后纽约北京浪登三地大屏幕直播那块儿颇有春晚风采。看了本片你会意识到：1.学好指环王，走遍nasa都不怕；2.学好种菜，走遍宇宙都不怕。3.马呆不哭躲起来撸！','2015-10-05 13:31:03'),(5,5,'艾小柯','还行','最精彩的还是Mark在火星上的生存体验，战胜一个个的不可能。美国英雄主义再次大放送，但因之前细节推陈的铺垫和节奏烘托，虽恶俗却也不乏感人。摄影质感依然保持了RS风，其余的情感刻画极尽精简。好看，但不隽永。3.5星。','2015-10-03 17:54:22'),(6,6,'小油飞','力荐','非常喜欢！这些年找一部不洒狗血不煽情的科幻片容易吗。要论科幻气质Ridley Scott比诺兰强太多了。喜剧的外表下是其实是格外正统的硬科幻路数，没有乱七八糟的感情线来喧宾夺主简直太棒。我最喜欢的地方是在求生的过程中完全没有强调对地球的执念，高潮甚至都不是回到地球，因为那完全不重要！','2015-10-03 11:23:15'),(7,7,'点金','力荐','本片完美展示了什么叫以逗逼的精神面对惨淡的人生 更加坚定了要做一个有逗逼精神的人 并且在逗逼的道路上找到一个一样具有逗逼精神的人','2015-10-03 12:43:19'),(8,8,'木卫二','还行','土豆的365种吃法？','2015-11-26 23:20:33'),(9,9,'Figaro小姐','力荐','10 of 10. 除了火星红色的奇妙美景以外，影片最大的魅力在于表达的浅尝辄止：看到了一点官僚主义，看到了一点“no one left behind”，看到了一点美式幽默感，但归根结底，这是关于一个人竭尽所能对抗自然的故事，关于人的无限潜力，关于宇宙的不可抗。这些不可预料在一部丰富的电影里显得单纯而迷人。','2015-10-04 13:26:04'),(10,10,'桃桃林林','推荐','这是一部难得很轻松的科幻片，影片有意弱化科幻片最常见的那些对未来以及未知宇宙的恐惧，而是大谈人定胜天和科学拯救人类。片中有着技术宅独有的蠢萌与乐观（当然，这也与马特·达蒙出色的表演密不可分）。即便影片在情感设定上略嫌套路，却仍能在关键时刻打动观众','2015-11-25 14:30:46'),(11,11,'黄青蕉','力荐','这部片子殴打了所有嚎叫“我们要新故事”的片方的脸。两百多年前的鲁滨逊漂流记放到太空拍一样精彩，爱我雷，请长命百岁','2015-11-29 15:16:26'),(12,12,'明安','推荐','马特达蒙你咋老浪费国家的钱……','2015-10-18 09:15:32'),(13,13,'72%海盐巧颗粒','力荐','太空电影可以不拍成一个人孤独战斗的缩影。无论多么绝望都剩下最后一点掐不灭的希望，这点太喜欢了，这种设定也很适合马特达蒙自身。','2015-10-03 12:14:33'),(14,14,'何倩彤','未评分','並無渲染宇宙的崇高華美，Ridley Scott給過我們一個由性、汗、血、黏液溝成的潮濕太空，現在給我們換一個質樸，沉實，粗礦，禁欲的。從前太空的恐怖在於we are not alone，現在太空的嚴酷在於we are on our own。','2015-10-03 01:15:53'),(15,15,'朝暮雪','推荐','经历了《星际穿越》那一劫，谁还敢去救你？','2015-11-25 02:33:19');
/*!40000 ALTER TABLE `comments_火星救援` ENABLE KEYS */;
UNLOCK TABLES;

