LOCK TABLES `comments_疯狂动物城` WRITE;
/*!40000 ALTER TABLE `comments_疯狂动物城` DISABLE KEYS */;
INSERT INTO `comments_疯狂动物城` VALUES (1,1,'悄悄','力荐','看过了这一部，我好像能够更坚定地说我会当迪士尼一辈子的粉丝。迪士尼给我们营造的乌托邦就是这样，永远善良勇敢，永远出乎意料。','2016-03-01 16:55:31'),(2,2,'Digit Fungi','力荐','无论是人设，世界观，动画制作，还是剧本，都挑不出毛病来啊啊啊！！细节多到爆！！好幸福！！！！>w< 最难能可贵的是配角们的人物性格和形象设置都非常饱满（教父梗好惊喜>< ） 虽然是动画，但是剧本还是隐射很多人类社会的种族问题，以及政治两党上位之争的问题。另外我狐Nick的眼神是在太苏了TwT...','2016-02-26 04:20:45'),(3,3,'影评终结者','力荐','完爆冰雪超能头脑，动物再次证明了动画片不止是给小朋友看的，而是全年龄段和世界级的，尖端数码特技、新意剧情、老梗新用搭配萌Q画风，乌托励志、搞笑温情、自然销魂、阴谋反转，用动物来映射人类，涉及种族歧视和两党斗争，无论从制作技术还是政治倾向或是社会意义来说，基本锁定今年奥斯卡最佳动画','2016-02-26 10:28:40'),(4,4,'羚羊的灵魂','力荐','做冰棍那机智的不像话！！！全片最爱！！！想吃！！！','2016-02-23 22:03:30'),(5,5,'黄青蕉','推荐','港真，面对人家动画片里连一把椅子扶手上的铝合金划痕都做得活灵活现的态度，咱们就默默低头学就好，不要一天到晚吹“国产视效大片”这个概念了，略尴尬','2016-03-07 20:47:43'),(6,6,'云淡风轻','力荐','不要看任何影评，如果可以预告片都别看，直接买票就好了。你要啥这电影里有啥！','2016-03-04 03:40:45'),(7,7,'tina','力荐','赞 看完赶脚世界都美好了','2016-03-01 16:29:52'),(8,8,'诗人橙子','力荐','绝对的好片子 裂墙推荐。实在是因为另一场满了…随手挑了这个片子。真是5分钟一小笑 10分钟哄堂大笑。看那个又懒又慢树獭简直要锤墙了。旁边法国妹子精辟的吐槽！看！这是我们法国人。我要憋到内伤了。最后散场大家都静坐着等着整首歌放完…五星好评。2016年度十佳。','2016-02-15 07:14:40'),(9,9,'方形月亮?','力荐','想嫁给又吊儿郎当又酷得不像话的狐狸先生。\n自认为是奥斯卡长篇动画的有力候选。\n啊啊啊，真的好好看，我要去二刷。','2016-02-28 16:31:09'),(10,10,'Marcus','力荐','赞到惊人，大迪斯尼动画一年比一年精彩！朱迪只身去陌生的大城市追梦，让我又追忆起自己那美好而充实的留学生活了。Sloth们的每次出场自己都要笑到面瘫了！而朱迪跟尼克哭着道歉的那段我也跟着哭了，朋友之间有时候就应该这样把脸拉下来好好道歉！总体反映的各种社会现象以及政治问题都很贴切到位。','2016-03-04 02:41:17'),(11,11,'✿Suda✿','力荐','超~~~~~~~~~~可爱的。大眼睛看得我都化了。一想到未来狐狸跟兔子可能有感情戏，我就hhhhhhhh。那只长耳朵的狐狸和那群二哈狼是我的笑点！！！','2016-02-28 21:18:36'),(12,12,'张小北','力荐','迪斯尼最近几年最好的一部动画片。不但娱乐性超强，而且主题和人物的深度也已超过一般动画片的维度了。','2016-03-05 10:43:01'),(13,13,'早日退休瑾朵朵','力荐','求同款录音笔！','2016-03-05 16:30:37'),(14,14,'北极熊','还行','最精彩的动画是用想象力拍出真实世界难以实现的故事，而不是用动物化填充一段如果是真人就普通到不能再普通的烂俗故事。笑料有，萌趣有，但更有的是莫名其妙的主旋律和政治正确，恐怕没有评分所体现的那么出色。','2016-03-04 21:02:44'),(15,15,'铎奇','力荐','妹想到，老娘弯了一世，被一只动画狐狸掰直了。兔子我也爱！迪士尼启用女性主演真是太成功了，迪士尼现在从小孩就倡导的男女无差别教育好棒噢。警局前台基佬豹好萌！','2016-03-05 10:55:39');
/*!40000 ALTER TABLE `comments_疯狂动物城` ENABLE KEYS */;
UNLOCK TABLES;

