/*!40000 ALTER TABLE `comments_达拉斯买家俱乐部` DISABLE KEYS */;
INSERT INTO `comments_达拉斯买家俱乐部` VALUES (1,1,'亵渎电影','推荐','满眼都是演技的片子，编导的功力都放在了两位戏霸身上了，一个皮包骨，一个异装癖，不是剧本给了他们多少戏肉，剧本多么偏袒他们，真的是这俩戏霸在用生命来演戏。其实这个从非法走私药物逐步到为人权抗争的故事本就很精彩，如今在两位戏霸面前，能让人印象深刻的也就是他俩的神演技了。★★★★','2014-01-04 23:43:57'),(2,2,'艾小柯','推荐','一流的表演，除口音尚可辨识，麦康纳已经完全成为了剧中人，Leto的表现也非常惊人，值得敬佩。平凡人在不平凡的状态下做出了超凡的选择，一个混混到民权斗士的转变之路，人终于超越了疾病。','2014-01-14 22:21:53'),(3,3,'陀螺凡达可','推荐','很不错的艾滋题材电影，同时涉及大量LGBT话题，本以为马修·麦康纳瘦成柴骨的奥斯卡级演技才是重点，但却是杰瑞德·莱托妖娆迷人的易装表演抢走风头惊艳全场。','2013-09-08 12:30:27'),(4,4,'桃桃林林','推荐','《瘟疫求生指南》的剧情版延伸，配合那个纪录片，将会了解他们的更多困难。这种正邪分明的片子虽然简单，但看起来很过瘾，两位男演员的努力让这部片子更有魅力。有几处细节很棒。比如超市遭遇旧同事，一场戏就把男主的立场和两位演员的关系转变都带出来了。杰瑞德·莱托比很多女演员都有魅力','2014-02-02 20:11:11'),(5,5,'巴喆','力荐','马修麦康纳和杰瑞德·莱托，他们两不拿小金人真是没天理。现在打赌，2014金球奖和奥斯卡，最佳男主或最佳男配，他们至少一个，若没得奖我吃键盘，上图。立此为据！！8.6（PS：键盘君终于舒了一口气，2014-3-3。= =！）','2014-01-10 20:54:12'),(6,6,'走马','推荐','艾滋是那头无法驯服的野牛，骑上它掉下来只是时间的问题，很好的比喻。','2014-07-26 19:01:05'),(7,7,'匡轶歌','力荐','男主、男配演技都破表了。上次见马修.麦康纳还是<林肯律师>里那个拉轰的帅叔，又屌又骚包，这部就眼窝眍䁖、腮帮塌陷、瘦到脱形的战艾斗士了。最诗意，是万千黄蝶绕身飞舞那一幕，如幻似真。对有些人来说，活着就是紧紧攥住意志力的缰绳，制服那头蹦跶公牛，尽量不从牛背颠下，能待多久，就待多久。','2014-01-08 13:26:41'),(8,8,'Fran','推荐','根据真实事件改编的纯剧情拍到这份上值了 男主男配的演技真心狂赞！','2013-11-12 02:03:40'),(9,9,'同志亦凡人中文站','力荐','用最轻松的态度拍出了最沉重的题材，完全不加煽情的感染人心。男演员们演技都大发了，今年Jared Leto不拿最佳男配我特么就撕逼！！！！','2014-01-04 14:15:44'),(10,10,'CharlesChou','力荐','Jared Leto的腿比女人还美！！！Jared Leto的腿比女人还美！！！Jared Leto的腿比女人还美！！！Jared Leto的腿比女人还美！！！【说正事，这热血抗艾片真是百年难遇地好啊，仔细想想，能把life outweighs money这种俗道理包在热血的外衣下讲得这么动情深刻。fuck yea cowboy!!!!','2014-01-05 19:08:52'),(11,11,'米粒','推荐','“药贩子的故事”只是个吸引人的题材，其实这部电影和去年的《瘟疫求生指南》一样，描绘了80年代的美国，多数治疗艾滋病的药品还未合法的时候，病人的生存状态，尤其是，LGBT群体的状态（还是用一个非常直的直男的故事来说的）。电影的开头非常好（后面再主次分明点就更好了），演员们非常勇敢。','2013-11-02 03:37:29'),(12,12,'大奇特(Grinch)','推荐','根据真人真事改编，生动再现了80年代艾滋病患者的生活状态和维权运动。从患者到药贩子本身就很励志，更何况他们对内不放弃生命、消除内部偏见；对外利大于弊的走私药与弊大于利的药监局之间相抗衡，温暖有力。两位演员真是用生命在演戏啊，用演技撑满全片！','2014-01-09 10:26:31'),(13,13,'davekozg','力荐','杰瑞德莱托必须最佳男配！演技好到发指！好到让人挠墙发指！马修麦康纳演技也好到爆，尤其是去墨西哥之前趴在方向盘上干嚎那一段，跪求两人冲击奥斯卡。一个沉重题材的电影却毫不伤感，最具震撼力量的是人性的真实，很难讨人喜欢的角色却让人充满敬意。PS：影片中段叙事节奏欠功力，五星是私心','2013-11-02 15:19:38'),(14,14,'Ron Chan','力荐','本片最打动我的地方是杰瑞德·莱托的那一句：“I don\'t wanna die”那种在垂死边缘挣扎的痛苦蔓延了整个电影，原来再堕落的人也有求生的欲望，而且他们比我们更痛苦，因为他们用玩世不恭来伪装自己。马修·麦康纳和杰瑞德·莱托的表演让人潸然泪下，他们值得一尊奥斯卡，直接五星送上！','2014-01-09 23:36:21'),(15,15,'wanderinglust','推荐','jared太屌了 T.T','2013-12-11 13:25:35');
/*!40000 ALTER TABLE `comments_达拉斯买家俱乐部` ENABLE KEYS */;
UNLOCK TABLES;

